from ute_ue.lteuepool import CfgFileBasedUePool
from ute_common_abstract_core.config import Config as CoreConfig


class AtCmdUePool(CfgFileBasedUePool):
    """UePool for At UEs"""

    def __init__(self, config_file_path=None, inline_config=None):
        """

        :param config_file_path:
        :param inline_config:
        """
        super(AtCmdUePool, self).__init__(config_file_path, inline_config)

    def create_device(self, device_name, device_config):
        """
        Create instance of ue

        :param device_name:
        :param device_config:
        :return: ue instance
        """
        app_servers_config = self._extract_app_servers_config()
        if app_servers_config:
            if 'data_transfer' not in device_config['CONSTRUCTOR_PARAMETERS']['configuration']:
                device_config['CONSTRUCTOR_PARAMETERS']['configuration']['data_transfer'] = {}
            device_config['CONSTRUCTOR_PARAMETERS']['configuration']['data_transfer']['APP_SERVERS'] = app_servers_config
        ver = self._extract_config_version()
        if ver:
            if 'data_transfer' not in device_config['CONSTRUCTOR_PARAMETERS']['configuration']:
                device_config['CONSTRUCTOR_PARAMETERS']['configuration']['data_transfer'] = {}
            device_config['CONSTRUCTOR_PARAMETERS']['configuration']['data_transfer']['VERSION'] = ver
        # hardcoded value, because plugin supports currently only ue_pc option
        # adb_shell option will be added in a future release
        device_config['CONSTRUCTOR_PARAMETERS']['configuration']['data_transfer']['iperf']['start_from'] = 'ue_pc'
        device = super(AtCmdUePool, self).create_device(device_name, device_config)
        return device

    @staticmethod
    def _extract_app_servers_config():
        # app_servers_config = CoreConfig().get_config(section='APP_SERVERS')
        app_servers_config = None
        whole_config = CoreConfig().get_config()
        if whole_config and ('APP_SERVERS' in whole_config):
            app_servers_config = whole_config['APP_SERVERS']
        return app_servers_config

    @staticmethod
    def _extract_config_version():
        ver = None
        whole_config = CoreConfig().get_config()
        if whole_config and ('VERSION' in whole_config):
            ver = whole_config['VERSION']
        return ver
